<div data-product-create-root data-product-modal class="product-crud-surface fixed inset-0 z-[100] hidden items-center justify-center bg-[#101633]/60 p-3 backdrop-blur-sm sm:p-6" role="dialog" aria-modal="true" aria-labelledby="product-create-modal-title">
    <button type="button" data-close-product-modal class="absolute inset-0 h-full w-full cursor-default" aria-label="Tutup formulir produk"></button>
    <section class="relative z-10 flex max-h-[calc(100vh-1.5rem)] w-full max-w-5xl flex-col overflow-hidden rounded-[28px] border border-[#e6eaff] bg-white shadow-[0_30px_100px_rgba(15,23,60,0.34)] sm:max-h-[calc(100vh-3rem)]">
        <header class="relative flex shrink-0 items-center justify-between gap-4 border-b border-[#edf0fb] px-5 py-4 sm:px-7 sm:py-5">
            <span class="absolute inset-x-0 top-0 h-1 bg-gradient-to-r from-[#536dfe] via-[#8293ff] to-[#54c8e8]"></span>
            <div class="flex min-w-0 items-center gap-4">
                <span class="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-gradient-to-br from-[#536dfe] to-[#8190ff] text-white shadow-lg shadow-[#536dfe]/20"><svg viewBox="0 0 24 24" class="h-6 w-6" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m4 7 8-4 8 4v10l-8 4-8-4V7Z"/><path d="m4 7 8 4 8-4M12 11v10"/></svg></span>
                <div class="min-w-0"><p class="text-xs font-bold uppercase tracking-[0.16em] text-[#687eff]">Katalog produk</p><h2 id="product-create-modal-title" class="mt-1 text-lg font-semibold tracking-tight text-[#20284a] sm:text-xl">Tambah produk</h2><p class="mt-1 hidden text-sm text-[#7b8299] sm:block">Tambahkan identitas, foto, harga, dan stok awal produk.</p></div>
            </div>
            <button type="button" data-close-product-modal class="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#f4f6fc] text-xl text-[#68708b] transition hover:rotate-90 hover:bg-[#e9edfa] focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-[#536dfe]/15" aria-label="Tutup">×</button>
        </header>

        <div class="min-h-0 flex-1 overflow-y-auto">
            <div data-product-message class="mx-5 mt-5 hidden rounded-xl border px-4 py-3 text-sm sm:mx-7" role="status" aria-live="polite"></div>
            <form data-product-form class="space-y-6 p-5 sm:p-7" enctype="multipart/form-data">
                <section class="space-y-4"><div><p class="text-xs font-bold uppercase tracking-[0.12em] text-[#687eff]">01 · Identitas</p><h3 class="mt-1 font-semibold text-[#20284a]">Nama dan pengelompokan</h3></div><div class="grid gap-4 sm:grid-cols-2">
                    <label class="space-y-1.5 text-sm font-semibold sm:col-span-2">Nama produk <span class="text-rose-600">*</span><input name="name" required maxlength="150" autocomplete="off" placeholder="Contoh: Kopi susu gula aren" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition placeholder:text-[#a1a8bc] focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold">SKU <span class="text-rose-600">*</span><input name="sku" required maxlength="80" autocomplete="off" placeholder="Contoh: KOPI-001" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal uppercase text-[#20284a] outline-none transition placeholder:normal-case placeholder:text-[#a1a8bc] focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold">Barcode <span class="font-normal text-[#8a91a9]">(opsional)</span><input name="barcode" maxlength="100" placeholder="Masukkan nomor barcode" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition placeholder:text-[#a1a8bc] focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <div class="space-y-1.5 sm:col-span-2"><div class="flex items-center justify-between gap-3"><label class="text-sm font-semibold">Kategori <span class="text-rose-600">*</span></label><button type="button" data-toggle-category class="text-sm font-semibold text-[#536dfe] transition hover:text-[#435ce7]">+ Buat kategori</button></div><select name="category_id" data-product-category required class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"><option value="">Memuat kategori…</option></select></div>
                    <label class="space-y-1.5 text-sm font-semibold sm:col-span-2">Deskripsi <span class="font-normal text-[#8a91a9]">(opsional)</span><textarea name="description" rows="2" placeholder="Jelaskan informasi penting produk" class="w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 py-3 text-sm font-normal text-[#20284a] outline-none transition placeholder:text-[#a1a8bc] focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></textarea></label>
                </div></section>

                <section class="space-y-4 border-t border-[#edf0fb] pt-6"><div><p class="text-xs font-bold uppercase tracking-[0.12em] text-[#687eff]">02 · Foto produk</p><h3 class="mt-1 font-semibold text-[#20284a]">Unggah foto</h3></div>
                    <div data-photo-dropzone class="group relative flex min-h-36 cursor-pointer flex-col items-center justify-center overflow-hidden rounded-2xl border-2 border-dashed border-[#cfd8f5] bg-[#fafbff] p-5 text-center transition hover:border-[#8293ff] hover:bg-[#f7f8ff] focus-within:border-[#687eff] focus-within:ring-4 focus-within:ring-[#536dfe]/10">
                        <input data-product-photo name="photo" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Pilih atau seret foto produk" class="absolute inset-0 z-10 h-full w-full cursor-pointer opacity-0">
                        <img data-photo-preview alt="Pratinjau foto produk" class="absolute inset-0 hidden h-full w-full object-contain p-3">
                        <div data-photo-empty class="pointer-events-none flex flex-col items-center"><span class="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#eef1ff] text-[#536dfe]"><svg viewBox="0 0 24 24" class="h-6 w-6" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m4 7 8-4 8 4v10l-8 4-8-4V7Z"/><path d="m4 7 8 4 8-4M12 11v10"/></svg></span><p class="mt-2 text-sm font-semibold text-[#303858]">Seret foto ke sini atau <span class="text-[#536dfe]">pilih file</span></p><p class="mt-1 text-xs text-[#8a91a9]">JPG, PNG, atau WebP · maksimal 3 MB</p></div>
                        <span data-photo-change class="pointer-events-none absolute bottom-3 z-20 hidden rounded-lg bg-[#20284a]/85 px-3 py-1.5 text-xs font-semibold text-white">Ganti foto</span>
                    </div>
                </section>

                <section class="space-y-4 border-t border-[#edf0fb] pt-6"><div><p class="text-xs font-bold uppercase tracking-[0.12em] text-[#687eff]">03 · Harga dan stok</p><h3 class="mt-1 font-semibold text-[#20284a]">Informasi penjualan</h3></div><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
                    <label class="space-y-1.5 text-sm font-semibold">Harga modal (Rp) <span class="text-rose-600">*</span><input name="purchase_price" type="number" min="0" step="1" required inputmode="numeric" placeholder="0" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold">Harga jual (Rp) <span class="text-rose-600">*</span><input name="selling_price" type="number" min="0" step="1" required inputmode="numeric" placeholder="0" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold">Satuan<input name="unit" maxlength="30" value="pcs" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold sm:col-span-2 xl:col-span-3">Lokasi toko <span class="text-rose-600">*</span><select name="business_id" data-product-outlet required class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"><option value="">Memuat lokasi toko…</option></select></label>
                    <label class="space-y-1.5 text-sm font-semibold">Stok awal <span class="text-rose-600">*</span><input name="initial_stock" type="number" min="0" step="1" required value="0" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                    <label class="space-y-1.5 text-sm font-semibold">Batas minimum<input name="minimum_stock" type="number" min="0" step="1" value="0" class="min-h-11 w-full rounded-xl border border-[#e4e8f4] bg-[#fafbff] px-3.5 text-sm font-normal text-[#20284a] outline-none transition focus:border-[#8697ff] focus:ring-4 focus:ring-[#536dfe]/10"></label>
                </div></section>

                <div class="flex flex-col-reverse gap-2 border-t border-[#edf0fb] pt-5 sm:flex-row sm:justify-end"><button type="button" data-close-product-modal class="inline-flex min-h-11 items-center justify-center rounded-xl border border-[#e4e8f4] bg-white px-4 text-sm font-semibold text-[#59617d] transition hover:bg-[#f8f9fd]">Batal</button><button type="submit" class="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-[#536dfe] to-[#687eff] px-5 text-sm font-semibold text-white shadow-[0_8px_18px_rgba(83,109,254,0.2)] transition hover:-translate-y-0.5 hover:from-[#435ce7] hover:to-[#596ff5] disabled:cursor-wait disabled:opacity-60"><svg viewBox="0 0 24 24" class="h-4 w-4" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M5 12h14m-7-7 7 7-7 7"/></svg>Simpan produk</button></div>
            </form>

            <section data-category-panel class="mx-5 mb-5 hidden rounded-2xl border border-[#e6eaff] bg-[#fafbff] p-4 sm:mx-7 sm:mb-7"><h3 class="font-semibold text-[#20284a]">Tambah kategori</h3><div data-category-message class="mt-3 hidden rounded-xl border border-rose-200 bg-rose-50 px-3 py-2 text-sm text-rose-700" role="alert"></div><form data-category-form class="mt-3 grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><input name="name" required maxlength="100" placeholder="Nama kategori" class="min-h-10 rounded-xl border border-[#e4e8f4] bg-white px-3 text-sm outline-none focus:border-[#687eff]"><input name="description" maxlength="2000" placeholder="Deskripsi (opsional)" class="min-h-10 rounded-xl border border-[#e4e8f4] bg-white px-3 text-sm outline-none focus:border-[#687eff]"><button type="submit" class="min-h-10 rounded-xl bg-[#20284a] px-4 text-sm font-semibold text-white disabled:opacity-60">Simpan kategori</button></form></section>
        </div>
    </section>
</div>
